function getClassKey(name) { return String(name || "Dark Knight").toLowerCase().replace(/[^a-z0-9]+/g, "_"); }
function getClassConfig() { return CLASS_CONFIG[selectedCharacterName] || CLASS_CONFIG["Dark Knight"]; }
document.querySelectorAll(".char-card").forEach(card => {
    card.addEventListener("click", () => {
        document.querySelectorAll(".char-card").forEach(c => c.classList.remove("selected"));
        card.classList.add("selected");
        selectedCharacterFile = card.dataset.file;
        selectedCharacterName = card.dataset.name;
        const savedInput = document.getElementById("hero-name");
        try {
            const profiles = JSON.parse(localStorage.getItem(CLASS_SAVE_KEY) || "{}");
            if (savedInput) savedInput.value = profiles[getClassKey(selectedCharacterName)]?.name || "";
        } catch (e) { if (savedInput) savedInput.value = ""; }
    });
});

