const groundRaycaster = new THREE.Raycaster();
groundRaycaster.far = 2000;
const downVector = new THREE.Vector3(0,-1,0);

function addChat(message, color = "#ddd") {
    const box = document.getElementById("chat-messages");
    const line = document.createElement("div");
    line.style.color = color;
    line.textContent = message;
    box.appendChild(line);
    box.scrollTop = box.scrollHeight;
}

function updateMyHpUI() {
    const pct = Math.max(0, Math.min(100, (myHP / maxHP) * 100));
    document.getElementById("ui-hp-bar").style.width = pct + "%";
    document.getElementById("ui-hp-text").textContent = `HP: ${Math.max(0, Math.round(myHP))} / ${maxHP}`;
}

function getGroundHeight(x, z, fallbackY = 0) {
    if (!mapMeshes.length) return fallbackY;
    groundRaycaster.set(new THREE.Vector3(x, 1000, z), downVector);
    const hits = groundRaycaster.intersectObjects(mapMeshes, true);
    for (const hit of hits) {
        if (hit.face && hit.face.normal) {
            const normal = hit.face.normal.clone();
            normal.transformDirection(hit.object.matrixWorld);
            if (normal.y > 0.25) return hit.point.y;
        }
    }
    return fallbackY;
}

