function buildClipFromData(D, name) {
    const times = [];
    for (let i = 0; i < D.n; i++) times.push(i / D.fps);
    const tracks = [];
    for (const bone in D.q) {
        tracks.push(new THREE.QuaternionKeyframeTrack(bone + ".quaternion", times, D.q[bone]));
    }
    tracks.push(new THREE.VectorKeyframeTrack(D.hips + ".position", times, D.p));
    return new THREE.AnimationClip(name, times[times.length - 1], tracks);
}

