function canonicalRigBoneName(name) {
    let value = String(name || "").split(/[:|]/).pop();
    value = value.replace(/_[0-9]+$/, "").replace(/\.[0-9]+$/, "");
    value = value.replace(/[^a-z0-9]/gi, "").toLowerCase();
    value = value.replace(/^mixamorig/, "");
    const finger = value.match(/^(thumb|index|middle|ring|pinky)([0-9]+)(?:leaf)?([lr])$/);
    if (finger) return (finger[3] === "r" ? "right" : "left") + "hand" + finger[1] + String(Number(finger[2]));
    const suffixSide = value.match(/^(clavicle|upperarm|lowerarm|hand|thigh|calf|foot|ball|toe)([lr])$/);
    if (suffixSide) value = (suffixSide[2] === "r" ? "right" : "left") + suffixSide[1];
    const aliases = {
        pelvis: "hips", hip: "hips",
        leftthigh: "leftupleg", thighleft: "leftupleg", leftupperleg: "leftupleg",
        rightthigh: "rightupleg", thighright: "rightupleg", rightupperleg: "rightupleg",
        leftcalf: "leftleg", calfleft: "leftleg", rightcalf: "rightleg", calfright: "rightleg",
        leftupperarm: "leftarm", upperarmleft: "leftarm", rightupperarm: "rightarm", upperarmright: "rightarm",
        leftlowerarm: "leftforearm", lowerarmleft: "leftforearm", rightlowerarm: "rightforearm", lowerarmright: "rightforearm",
        leftclavicle: "leftshoulder", clavicleleft: "leftshoulder", rightclavicle: "rightshoulder", clavicleright: "rightshoulder",
        lefttoe: "lefttoebase", righttoe: "righttoebase", neck01: "neck", chest: "spine02"
    };
    return aliases[value] || value;
}
function findRetargetBone(root, sourceName) {
    const wanted = canonicalRigBoneName(sourceName);
    const allowSourceNodes = !!(root.userData && root.userData.allowRetargetNodes);
    let found = null;
    root.traverse(function(node) {
        if (!found && (node.isBone || allowSourceNodes) && canonicalRigBoneName(node.name) === wanted) found = node;
    });
    return found;
}
function getRetargetRigHeight(root) {
    if (!root) return 0;
    const hips = findRetargetBone(root, "Hips");
    const head = findRetargetBone(root, "Head") || findRetargetBone(root, "Neck");
    if (!hips || !head) return 0;
    root.updateMatrixWorld(true);
    const inverseRoot = root.matrixWorld.clone().invert();
    const hipsPosition = hips.getWorldPosition(new THREE.Vector3()).applyMatrix4(inverseRoot);
    const headPosition = head.getWorldPosition(new THREE.Vector3()).applyMatrix4(inverseRoot);
    return hipsPosition.distanceTo(headPosition);
}
function getRetargetPositionScale(sourceRoot, targetRoot) {
    const sourceHeight = getRetargetRigHeight(sourceRoot);
    const targetHeight = getRetargetRigHeight(targetRoot);
    const sourceHips = findRetargetBone(sourceRoot, "Hips");
    const targetHips = findRetargetBone(targetRoot, "Hips");
    if (!sourceHips || !targetHips || !sourceHeight || !targetHeight) return 1;
    const sourceRootScale = sourceRoot.getWorldScale(new THREE.Vector3());
    const targetRootScale = targetRoot.getWorldScale(new THREE.Vector3());
    const sourceParentScale = (sourceHips.parent || sourceRoot).getWorldScale(new THREE.Vector3());
    const targetParentScale = (targetHips.parent || targetRoot).getWorldScale(new THREE.Vector3());
    const sourceLocalParentScale = sourceParentScale.y / (sourceRootScale.y || 1);
    const targetLocalParentScale = targetParentScale.y / (targetRootScale.y || 1);
    const ratio = (targetHeight / sourceHeight) * (sourceLocalParentScale / (targetLocalParentScale || 1));
    return Number.isFinite(ratio) && ratio > 0 ? ratio : 1;
}
function retargetAnimationClip(sourceClip, sourceRoot, targetRoot, options = {}) {
    if (!sourceClip || !sourceRoot || !targetRoot || !sourceClip.tracks) return null;
    sourceRoot.updateMatrixWorld(true);
    targetRoot.updateMatrixWorld(true);
    const tracks = [];
    const mappedBones = new Set();
    let hasHipsPosition = false;
    const positionScale = options.scalePositions ? getRetargetPositionScale(sourceRoot, targetRoot) : 1;
    sourceClip.tracks.forEach(function(track) {
        const separator = track.name.lastIndexOf(".");
        if (separator < 1) return;
        const sourceName = track.name.slice(0, separator);
        const property = track.name.slice(separator + 1);
        if (["position", "quaternion", "scale"].indexOf(property) < 0) return;
        const sourceBone = findRetargetBone(sourceRoot, sourceName);
        const targetBone = findRetargetBone(targetRoot, sourceName);
        if (!sourceBone || !targetBone) return;
        const copy = track.clone();
        copy.name = targetBone.name + "." + property;
        const values = copy.values;
        if (property === "position") {
            const pinnedHips = options.pinHips && canonicalRigBoneName(sourceName) === "hips";
            const firstHipsY = values.length >= 2 ? values[1] : sourceBone.position.y;
            for (let i = 0; i < values.length; i += 3) {
                values[i] = pinnedHips
                    ? targetBone.position.x
                    : targetBone.position.x + (values[i] - sourceBone.position.x) * positionScale;
                values[i + 1] = targetBone.position.y + (values[i + 1] - (pinnedHips ? firstHipsY : sourceBone.position.y)) * positionScale;
                values[i + 2] = pinnedHips
                    ? targetBone.position.z
                    : targetBone.position.z + (values[i + 2] - sourceBone.position.z) * positionScale;
            }
        } else if (property === "quaternion") {
            const sourceRestInverse = sourceBone.quaternion.clone().invert();
            for (let i = 0; i < values.length; i += 4) {
                const animated = new THREE.Quaternion(values[i], values[i + 1], values[i + 2], values[i + 3]);
                const adjusted = targetBone.quaternion.clone().multiply(sourceRestInverse).multiply(animated).normalize();
                adjusted.toArray(values, i);
            }
        } else if (property === "scale") {
            for (let i = 0; i < values.length; i += 3) {
                values[i] *= targetBone.scale.x / (sourceBone.scale.x || 1);
                values[i + 1] *= targetBone.scale.y / (sourceBone.scale.y || 1);
                values[i + 2] *= targetBone.scale.z / (sourceBone.scale.z || 1);
            }
        }
        tracks.push(copy);
        mappedBones.add(canonicalRigBoneName(sourceName));
        if (canonicalRigBoneName(sourceName) === "hips" && property === "position") hasHipsPosition = true;
    });
    const required = ["hips", "rightarm", "rightforearm"];
    const hasSpine = Array.from(mappedBones).some(function(name) { return name === "spine" || /^spine[0-9]+$/.test(name); });
    if (!hasHipsPosition || tracks.length < 12 || !hasSpine || required.some(function(name) { return !mappedBones.has(name); })) return null;
    return new THREE.AnimationClip(sourceClip.name + "_Retargeted", sourceClip.duration, tracks);
}
function buildSwordAttackClip(root = characterModel, sourceRoot = null) {
    if (!root) throw new Error("Nu există un rig de personaj pentru retargetare.");
    const D = SWORD_ATTACK_DATA;
    const times = [];
    for (let i = 0; i < D.n; i++) times.push(i / D.fps);
    const tracks = [];
    if (sourceRoot) {
        for (const bone in D.q) {
            const sourceBone = findRetargetBone(sourceRoot, bone);
            if (sourceBone) tracks.push(new THREE.QuaternionKeyframeTrack(sourceBone.name + ".quaternion", times, D.q[bone]));
        }
        const sourceHips = findRetargetBone(sourceRoot, D.hips);
        if (sourceHips) tracks.push(new THREE.VectorKeyframeTrack(sourceHips.name + ".position", times, D.p));
        const sourceClip = new THREE.AnimationClip("SwordAttack_Source", times[times.length - 1], tracks);
        const retargeted = retargetAnimationClip(sourceClip, sourceRoot, root);
        if (!retargeted) throw new Error("Rigul nu a putut primi animația de atac.");
        retargeted.name = "SwordAttack_Retargeted";
        return retargeted;
    }
    const mappedBones = [];
    for (const bone in D.q) {
        const targetBone = findRetargetBone(root, bone);
        if (targetBone) {
            tracks.push(new THREE.QuaternionKeyframeTrack(targetBone.name + ".quaternion", times, D.q[bone]));
            mappedBones.push(canonicalRigBoneName(bone));
        }
    }
    const targetHips = findRetargetBone(root, D.hips);
    const required = ["hips", "spine", "rightarm", "rightforearm"];
    if (!targetHips || mappedBones.length < 12 || required.some(function(name) { return mappedBones.indexOf(name) < 0; })) {
        throw new Error("Rigul nu are suficiente oase compatibile cu animația de atac.");
    }
    tracks.push(new THREE.VectorKeyframeTrack(targetHips.name + ".position", times, D.p));
    return new THREE.AnimationClip("SwordAttack_Retargeted", times[times.length - 1], tracks);
}

/* ====================== PROGRES, INVENTAR, SALVARE ====================== */
const SAVE_KEY = "mu_dark_fantasy_save_v1";
const CLASS_SAVE_KEY = "mu_dark_fantasy_class_saves_v1";
const MAX_LEVEL = 50;
let gameStarted = false;
let heroName = "Dark Knight";
let playerLevel = 1, playerXP = 0;
let gold = 0, hpPotions = 0, mpPotions = 0, crystals = 0;
let damageMult = 1;
let saveTimer = null;
let potionReadyAt = 0;

function xpForLevel(l) { return Math.round(100 * Math.pow(l, 1.5)); }

function cleanHeroName(v) {
    const t = String(v || "").replace(/[^\p{L}\p{N} _-]/gu, "").trim().slice(0, 14);
    return t || "Dark Knight";
}
function loadGame() {
    try {
        const profiles = JSON.parse(localStorage.getItem(CLASS_SAVE_KEY) || "{}");
        const key = getClassKey(selectedCharacterName);
        let raw = profiles[key] ? JSON.stringify(profiles[key]) : null;
        // Migrate the existing single-slot save to Dark Knight without ever
        // assigning it to another class or deleting the original key.
        if (!raw && selectedCharacterName === "Dark Knight") raw = localStorage.getItem(SAVE_KEY);
        if (!raw) {
            heroName = selectedCharacterName;
            playerLevel = 1; playerXP = 0; gold = 0;
            hpPotions = 0; mpPotions = 0; crystals = 0;
            monsterKills = 0; bossKills = 0; pvpKills = 0;
            stats.str = 0; stats.vit = 0; stats.int = 0; stats.agi = 0; statPoints = 0;
            skillLv = [0, 1, 0, 0, 0, 0, 0, 0]; skillPoints = 3;
            bag = new Array(BAG_SIZE).fill(null);
            SLOTS.forEach(function(sl) { equipped[sl] = null; });
            return;
        }
        const d = JSON.parse(raw);
        const num = function(v, lo, hi, def) {
            v = Math.floor(Number(v));
            return Number.isFinite(v) ? Math.max(lo, Math.min(hi, v)) : def;
        };
        heroName = cleanHeroName(d.name);
        playerLevel = num(d.level, 1, MAX_LEVEL, 1);
        playerXP = num(d.xp, 0, 1e9, 0);
        gold = num(d.gold, 0, 1e9, 0);
        hpPotions = num(d.hpPotions, 0, 9999, 0);
        mpPotions = num(d.mpPotions, 0, 9999, 0);
        crystals = num(d.crystals, 0, 9999, 0);
        monsterKills = num(d.monsterKills, 0, 1e9, 0);
        bossKills = num(d.bossKills, 0, 1e9, 0);
        pvpKills = num(d.pvpKills, 0, 1e9, 0);

        // puncte de caracter (salvările vechi primesc retroactiv 3 puncte pe nivel)
        if (d.stats && typeof d.stats === "object") {
            stats.str = num(d.stats.str, 0, 999, 0);
            stats.vit = num(d.stats.vit, 0, 999, 0);
            stats.int = num(d.stats.int, 0, 999, 0);
            stats.agi = num(d.stats.agi, 0, 999, 0);
            statPoints = num(d.statPoints, 0, 9999, 0);
        } else {
            statPoints = 3 * (playerLevel - 1);
        }

        // abilități (salvările vechi aveau abilitățile 1-4 deja disponibile)
        if (Array.isArray(d.skillLv)) {
            for (let n = 1; n <= 7; n++) skillLv[n] = num(d.skillLv[n], 0, SKILL_MAX_LV, 0);
            if (skillLv[1] < 1) skillLv[1] = 1;
            skillPoints = num(d.skillPoints, 0, 9999, 0);
        } else {
            for (let n = 1; n <= 7; n++) skillLv[n] = n <= 4 ? 1 : 0;
            skillPoints = Math.max(0, 2 * (playerLevel - 1) + bossKills);
        }

        // echipament și rucsac
        bag = new Array(BAG_SIZE).fill(null);
        if (Array.isArray(d.bag)) {
            for (let i = 0; i < BAG_SIZE && i < d.bag.length; i++) bag[i] = sanitizeItem(d.bag[i]);
        }
        SLOTS.forEach(function(sl) { equipped[sl] = null; });
        if (d.equipped && typeof d.equipped === "object") {
            SLOTS.forEach(function(sl) {
                const it = sanitizeItem(d.equipped[sl] || (sl === "necklace" ? d.equipped.amulet : null));
                if (it && it.slot === sl) equipped[sl] = it;
            });
        } else if (d.equip && typeof d.equip === "object") {
            // format vechi: trepte cumpărate -> obiecte echipate
            [["weapon", "weapon"], ["armor", "armor"], ["amulet", "necklace"]].forEach(function(p) {
                const tier = num(d.equip[p[0]], 0, 4, 0);
                if (tier > 0) equipped[p[1]] = shopItem(p[1], tier - 1);
            });
        }
    } catch (e) {
        console.warn("Salvarea nu a putut fi citită:", e);
    }
}

function saveNow() {
    if (!gameStarted) return;
    try {
        const profile = {
            name: heroName, level: playerLevel, xp: playerXP, gold: gold,
            hpPotions: hpPotions, mpPotions: mpPotions, crystals: crystals,
            monsterKills: monsterKills, bossKills: bossKills, pvpKills: pvpKills,
            stats: stats, statPoints: statPoints, bag: bag, equipped: equipped,
            skillLv: skillLv, skillPoints: skillPoints
        };
        const profiles = JSON.parse(localStorage.getItem(CLASS_SAVE_KEY) || "{}");
        profiles[getClassKey(selectedCharacterName)] = profile;
        localStorage.setItem(CLASS_SAVE_KEY, JSON.stringify(profiles));
        if (selectedCharacterName === "Dark Knight") localStorage.setItem(SAVE_KEY, JSON.stringify(profile));
    } catch (e) {}
}

function saveGame() {
    if (saveTimer) return;
    saveTimer = setTimeout(function() { saveTimer = null; saveNow(); }, 800);
}
window.addEventListener("beforeunload", saveNow);

// numele salvat apare deja în ecranul de start
(function() {
    try {
        const profiles = JSON.parse(localStorage.getItem(CLASS_SAVE_KEY) || "{}");
        const raw = profiles[getClassKey(selectedCharacterName)]
            ? JSON.stringify(profiles[getClassKey(selectedCharacterName)])
            : (selectedCharacterName === "Dark Knight" ? localStorage.getItem(SAVE_KEY) : null);
        const input = document.getElementById("hero-name");
        if (raw && input) input.value = cleanHeroName(JSON.parse(raw).name);
    } catch (e) {}
})();

function recalcStats(fullHeal) {
    const g = gearTotals();
    const passive = getClassConfig().stats;
    maxHP = Math.round((1500 + (playerLevel - 1) * 120 + g.hp + stats.vit * 45) * passive.hp);
    maxMP = Math.round((700 + (playerLevel - 1) * 40 + g.mp + stats.int * 25) * passive.mp);
    damageMult = passive.damage * (1 + (playerLevel - 1) * 0.08) * (1 + g.dmg + stats.str * 0.015);
    critChance = Math.min(0.75, 0.15 + passive.crit + g.crit + stats.agi * 0.0035);
    moveMult = passive.speed * (1 + Math.min(0.35, g.speed + stats.agi * 0.0025));
    spellMult = passive.spell * (1 + stats.int * 0.015);
    defense = Math.min(0.65, passive.defense + g.def);
    if (fullHeal) { myHP = maxHP; myMP = maxMP; }
    else { myHP = Math.min(myHP, maxHP); myMP = Math.min(myMP, maxMP); }
}

function updateNameUI() {
    document.getElementById("ui-name").textContent = heroName + " · Lv." + playerLevel;
}

function updateXpUI() {
    const need = xpForLevel(playerLevel);
    document.getElementById("ui-xp-bar").style.width = Math.min(100, playerXP / need * 100) + "%";
    document.getElementById("ui-xp-text").textContent = "XP " + playerXP + " / " + need;
}

function updateInvUI() {
    document.getElementById("inv-gold").textContent = gold;
    document.getElementById("inv-hp").textContent = hpPotions;
    document.getElementById("inv-mp").textContent = mpPotions;
    document.getElementById("inv-crystal").textContent = crystals;
    const b = document.getElementById("btn-char");
    if (b) b.classList.toggle("alert", statPoints > 0);
    const bs = document.getElementById("btn-skill");
    if (bs) bs.classList.toggle("alert", skillPoints > 0);
    updateSkillBar();
    if (invOpen) renderInventory();
    if (charOpen) renderCharacter();
    if (shopOpen) renderShop();
    if (skillOpen) renderSkills();
}

function sendHp() {
    if (!socket || !socket.connected) return;
    lastHpSent = Math.round(myHP);
    socket.emit("hpUpdate", { hp: lastHpSent, max: maxHP });
}

function levelUpEffect() {
    sndLevelUp();
    spawnFloatingText("LEVEL UP!", "#ffd700",
        new THREE.Vector3(myPos.x, myPos.y + PLAYER_HEIGHT + 1.0, myPos.z), true);
    spawnSlashEffect(myPos.x, myPos.y, myPos.z, 0, 2);
    for (let k = 0; k < 28; k++) {
        const a = Math.random() * Math.PI * 2;
        const sp = 2 + Math.random() * 3;
        spawnParticle(myPos.x, myPos.y + 0.5, myPos.z, Math.cos(a) * sp, 3 + Math.random() * 3, Math.sin(a) * sp, 0xffd34d, 0.22, 0.9);
    }
}

function gainXP(amount) {
    if (amount <= 0) return;
    playerXP += amount;
    spawnFloatingText("+" + amount + " XP", "#ffd966",
        new THREE.Vector3(myPos.x, myPos.y + PLAYER_HEIGHT + 0.9, myPos.z), false);
    let gained = 0;
    while (playerLevel < MAX_LEVEL && playerXP >= xpForLevel(playerLevel)) {
        playerXP -= xpForLevel(playerLevel);
        playerLevel++;
        gained++;
    }
    if (playerLevel >= MAX_LEVEL) playerXP = Math.min(playerXP, xpForLevel(MAX_LEVEL) - 1);
    if (gained) {
        statPoints += 3 * gained;
        skillPoints += 2 * gained;
        recalcStats(true);
        levelUpEffect();
        addChat("⭐ Nivel " + playerLevel + "! Viață, mană și daune au crescut.", "#ffd700");
        addChat("✨ Ai primit " + (3 * gained) + " puncte de caracter (P) și " + (2 * gained) + " puncte de abilitate (K).", "#ffd700");
        updateNameUI();
        if (socket && socket.connected) {
            socket.emit("levelUpdate", { level: playerLevel });
            sendHp();
        }
        updateInvUI();
    }
    updateXpUI();
    saveGame();
    sendStatsSoon();
}

function usePotion(kind) {
    if (playerDead || !gameStarted) return;
    const now = nowSec();
    if (now < potionReadyAt) return;
    if (kind === "hp") {
        if (hpPotions <= 0) { addChat("Nu ai poțiuni de viață.", "#e74c3c"); return; }
        if (myHP >= maxHP) return;
        hpPotions--;
        const heal = Math.round(maxHP * 0.35);
        myHP = Math.min(maxHP, myHP + heal);
        spawnFloatingText("+" + heal, "#4cff7a", new THREE.Vector3(myPos.x, myPos.y + PLAYER_HEIGHT + 0.6, myPos.z), false);
        sendHp();
    } else {
        if (mpPotions <= 0) { addChat("Nu ai poțiuni de mană.", "#e74c3c"); return; }
        if (myMP >= maxMP) return;
        mpPotions--;
        const gain = Math.round(maxMP * 0.4);
        myMP = Math.min(maxMP, myMP + gain);
        spawnFloatingText("+" + gain, "#5db2ff", new THREE.Vector3(myPos.x, myPos.y + PLAYER_HEIGHT + 0.6, myPos.z), false);
    }
    potionReadyAt = now + 1;
    sndPotion();
    updateMyHpUI();
    updateMyMpUI();
    updateInvUI();
    saveGame();
}

/* ====================== SĂRITURĂ ====================== */
const JUMP_SPEED = 9.5;
const GRAVITY = 28;
let jumpOffset = 0, jumpVel = 0, jumping = false;
let jumpAction = null;
let shakeT = 0;

function addShake(v) { shakeT = Math.max(shakeT, v); }

function doJump() {
    if (!characterLoaded || playerDead || jumping || nowSec() < rollUntil) return;
    jumping = true;
    jumpVel = JUMP_SPEED;
    jumpOffset = 0.001;
    sndJump();
    spawnDust(myPos.x, myPos.y, myPos.z, 5, 0.6);
    if (jumpAction && nowSec() >= attackUntil) playOneShot(jumpAction, 1);
}

/* ====================== DROP-URI ====================== */
const lootItems = {};
const LOOT_COLORS = { gold: 0xffcc33, hp: 0xff3b3b, mp: 0x3b8bff, crystal: 0xb06bff };

function lootColor(l) {
    if (l.type === "gear" && RARITY_INFO[l.rarity]) return parseInt(RARITY_INFO[l.rarity].color.slice(1), 16);
    return LOOT_COLORS[l.type] || 0xffffff;
}

function createLootVisual(l) {
    const group = new THREE.Group();
    const spin = new THREE.Group();
    const color = lootColor(l);
    const type = l.type;
    const mat = new THREE.MeshStandardMaterial({ color: color, emissive: color, emissiveIntensity: 0.45, metalness: 0.5, roughness: 0.35 });

    if (type === "gold") {
        const coin = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, 0.08, 18), mat);
        coin.rotation.x = Math.PI / 2;
        spin.add(coin);
    } else if (type === "crystal") {
        spin.add(new THREE.Mesh(new THREE.OctahedronGeometry(0.42), mat));
    } else if (type === "gear") {
        const chest = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.4, 0.5), mat);
        const lid = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.7, 10, 1, false, 0, Math.PI), mat);
        lid.rotation.z = Math.PI / 2;
        lid.position.y = 0.2;
        spin.add(chest);
        spin.add(lid);
    } else {
        const flask = new THREE.Mesh(new THREE.SphereGeometry(0.3, 12, 10), mat);
        const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.12, 0.28, 8), mat);
        neck.position.y = 0.36;
        spin.add(flask);
        spin.add(neck);
    }
    spin.position.y = 0.9;
    group.add(spin);

    const high = type === "gear" && (l.rarity === "epic" || l.rarity === "legendary");
    const beam = new THREE.Mesh(
        new THREE.CylinderGeometry(0.07, 0.07, high ? 6 : 3.2, 8, 1, true),
        new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: 0.3, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
    );
    beam.position.y = high ? 3 : 1.6;
    group.add(beam);
    return { group: group, spin: spin, beam: beam };
}

function addLootItem(l) {
    if (!l || lootItems[l.id] || !scene) return;
    const vis = createLootVisual(l);
    const y = getGroundHeight(l.x, l.z, 0);
    vis.group.position.set(l.x, y, l.z);
    vis.group.userData = { pickType: "loot", pickId: l.id };
    scene.add(vis.group);
    lootItems[l.id] = {
        id: l.id, type: l.type, amount: l.amount, x: l.x, z: l.z,
        slot: l.slot, rarity: l.rarity, ilvl: l.ilvl, seed: l.seed,
        group: vis.group, spin: vis.spin, beam: vis.beam,
        t: Math.random() * 6, pending: 0, needGround: !mapLoaded, warnAt: 0
    };
}

function removeLootItem(id) {
    const it = lootItems[id];
    if (!it) return;
    scene.remove(it.group);
    it.group.traverse(function(n) {
        if (n.geometry) n.geometry.dispose();
        if (n.material) n.material.dispose();
    });
    delete lootItems[id];
}

function clearLoot() {
    for (const id in lootItems) removeLootItem(id);
}

function updateLoot(delta, now) {
    for (const id in lootItems) {
        const it = lootItems[id];
        it.t += delta;
        if (it.needGround && mapLoaded) {
            it.group.position.y = getGroundHeight(it.x, it.z, 0);
            it.needGround = false;
        }
        it.spin.rotation.y += 2 * delta;
        it.spin.position.y = 0.9 + Math.sin(it.t * 3) * 0.12;
        it.beam.material.opacity = 0.22 + 0.12 * Math.sin(it.t * 4);

        if (!playerDead && socket && socket.connected && now >= it.pending &&
            Math.hypot(myPos.x - it.x, myPos.z - it.z) < 1.9) {
            if (it.type === "gear" && freeSlots() === 0) {
                if (now >= it.warnAt) {
                    it.warnAt = now + 4;
                    addChat("🎒 Inventarul este plin! Eliberează un loc (I) ca să ridici obiectul.", "#e74c3c");
                    sndError();
                }
                continue;
            }
            it.pending = now + 1.2;
            socket.emit("pickupLoot", { id: id });
        }
    }
}

function applyLootGranted(d) {
    if (!d) return;
    const amount = Math.max(1, Math.floor(Number(d.amount)) || 1);
    const pos = new THREE.Vector3(myPos.x, myPos.y + PLAYER_HEIGHT + 0.5, myPos.z);
    if (d.type === "gold") {
        gold += amount;
        sndCoin();
        spawnFloatingText("+" + amount + " aur", "#ffd34d", pos, false);
    } else if (d.type === "hp") {
        hpPotions += amount;
        sndPickup();
        spawnFloatingText("Poțiune de viață", "#ff6b6b", pos, false);
        addChat("🧪 Ai găsit o poțiune de viață.", "#ff9a9a");
    } else if (d.type === "mp") {
        mpPotions += amount;
        sndPickup();
        spawnFloatingText("Poțiune de mană", "#6bb8ff", pos, false);
        addChat("💧 Ai găsit o poțiune de mană.", "#8ec9ff");
    } else if (d.type === "crystal") {
        crystals += amount;
        sndCrystal();
        spawnFloatingText("Cristal!", "#c792ff", pos, true);
        addChat("💎 Ai găsit un cristal rar!", "#c792ff");
    } else if (d.type === "gear") {
        const item = makeGear(d.slot, d.rarity, d.ilvl, d.seed);
        if (item) {
            const ri = RARITY_INFO[item.rarity];
            if (addToBag(item) >= 0) {
                if (RARITY.indexOf(item.rarity) >= 2) sndCrystal(); else sndPickup();
                spawnFloatingText(item.name, ri.color, pos, RARITY.indexOf(item.rarity) >= 3);
                addChat("🎁 Ai găsit: " + item.name + " (" + ri.label + ", nivel " + item.lvl + ")", ri.color);
            } else {
                const p = sellPrice(item);
                gold += p;
                sndCoin();
                addChat("🎒 Inventar plin: " + item.name + " a fost vândut automat pentru " + p + " aur.", "#e67e22");
            }
        }
    }
    updateInvUI();
    saveGame();
}

/* ====================== BOSS: AVERTIZARE + UNDĂ DE ȘOC ====================== */
const telegraphs = [];

function addTelegraph(x, z, r, t) {
    if (!scene) return;
    const y = getGroundHeight(x, z, 0) + 0.15;
    const geo = new THREE.CircleGeometry(r, 48);
    const mat = new THREE.MeshBasicMaterial({ color: 0xff2200, transparent: true, opacity: 0.25, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(x, y, z);
    scene.add(mesh);
    telegraphs.push({ mesh: mesh, geo: geo, mat: mat, life: 0, max: t, x: x, z: z, r: r });
    addChat("⚠️ Lordul Infernului pregătește o lovitură în sol! Fugi din cerc sau rostogolește-te (C)!", "#ff8a65");
}

function updateTelegraphs(delta) {
    for (let i = telegraphs.length - 1; i >= 0; i--) {
        const t = telegraphs[i];
        t.life += delta;
        t.mat.opacity = 0.18 + 0.3 * Math.abs(Math.sin(t.life * 9));
        if (t.life >= t.max) {
            scene.remove(t.mesh);
            t.geo.dispose();
            t.mat.dispose();
            telegraphs.splice(i, 1);
        }
    }
}

function spawnShockwave(x, z, r) {
    if (!scene) return;
    const y = getGroundHeight(x, z, 0) + 0.3;
    const group = new THREE.Group();
    group.position.set(x, y, z);
    const geo = new THREE.RingGeometry(r * 0.82, r, 64);
    const mat = new THREE.MeshBasicMaterial({ color: 0xff3322, transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    group.add(mesh);
    group.scale.setScalar(0.3);
    scene.add(group);
    effects.push({ group: group, mat: mat, geo: geo, life: 0, max: 0.6, skill: 3 });
    for (let k = 0; k < 24; k++) {
        const a = Math.random() * Math.PI * 2;
        const sp = 4 + Math.random() * 6;
        spawnParticle(x, y + 0.3, z, Math.cos(a) * sp, 1 + Math.random() * 3, Math.sin(a) * sp, 0xff6a3d, 0.25, 0.6);
    }
    if (Math.hypot(myPos.x - x, myPos.z - z) < 40) addShake(0.6);
}

/* ====================== LUMEA DE PE SERVER: MONȘTRI ====================== */
const monsterById = {};
const MONSTER_TINTS = [0x6b1f2a, 0x3c2a6b, 0x2a5a3a];
let wantSpawnPoints = false;

function clearMonsters() {
    for (const m of monsters) scene.remove(m.root);
    monsters.length = 0;
    for (const id in monsterById) delete monsterById[id];
}

function addMonsterFromServer(info) {
    if (!info || monsterById[info.id] || !scene) return;
    const boss = info.type === "boss";
    const scale = info.scale || 1;
    const built = createMonsterMesh(boss ? 0x8a1414 : MONSTER_TINTS[monsters.length % MONSTER_TINTS.length], scale, boss);
    const bar = makeBarSprite(info.name || "Demon");
    bar.sprite.position.set(0, 3.0 * scale, 0);
    if (boss) bar.sprite.scale.set(5.2, 1.3, 1);
    built.root.add(bar.sprite);
    built.root.userData = { pickType: "monster", pickId: info.id };

    const y = getGroundHeight(info.x, info.z, 0);
    built.root.position.set(info.x, y, info.z);
    scene.add(built.root);

    const m = {
        id: info.id, boss: boss, scale: scale, name: info.name || (boss ? "Lordul Infernului" : "Demon"),
        root: built.root, model: built.model, bodyMat: built.bodyMat, bar: bar,
        x: info.x, y: y, z: info.z, tx: info.x, tz: info.z, gy: y,
        face: 0, hp: info.hp, maxHp: info.maxHp, shownHp: info.hp,
        alive: info.alive !== false,
        attackCount: 0, attackSeen: 0, attackT: 0, flash: 0, deathT: 0,
        groundTimer: Math.random() * 0.1, phase: Math.random() * 6, needGround: !mapLoaded
    };
    m.bar.draw(m.hp / m.maxHp);
    if (!m.alive) {
        m.deathT = 2;
        m.root.visible = false;
        m.bar.sprite.visible = false;
    }
    monsters.push(m);
    monsterById[m.id] = m;
}

function killMonsterVisual(m) {
    sndMonsterDie(Math.hypot(m.x - myPos.x, m.z - myPos.z), m.boss);
    m.alive = false;
    m.deathT = 0;
    m.bar.sprite.visible = false;
    if (m.boss && Math.hypot(m.x - myPos.x, m.z - myPos.z) < 80) addShake(0.4);
}

function respawnMonsterVisual(m, s) {
    m.alive = true;
    m.x = m.tx = s.x;
    m.z = m.tz = s.z;
    m.hp = m.maxHp;
    m.shownHp = m.maxHp;
    m.attackSeen = s.c;
    m.attackT = 0;
    m.deathT = 0;
    m.root.visible = true;
    m.model.rotation.x = 0;
    m.bar.sprite.visible = true;
    m.bar.draw(1);
    m.gy = getGroundHeight(m.x, m.z, m.y);
    m.y = m.gy;
    m.root.position.set(m.x, m.y, m.z);
}

function handleWorldState(data) {
    if (!data || !scene) return;
    clearMonsters();
    clearLoot();
    for (const info of (data.monsters || [])) addMonsterFromServer(info);
    for (const l of (data.loot || [])) addLootItem(l);
    setLoad("world", 1);
}

function handleMonsterSnapshot(arr) {
    if (!Array.isArray(arr)) return;
    for (const s of arr) {
        const m = monsterById[s.id];
        if (!m) continue;
        m.tx = s.x;
        m.tz = s.z;
        m.face = s.f;
        m.attackCount = s.c;
        if (m.alive && !s.a) killMonsterVisual(m);
        else if (!m.alive && s.a) respawnMonsterVisual(m, s);
        if (s.a && m.shownHp !== s.hp) {
            m.shownHp = s.hp;
            m.hp = s.hp;
            m.bar.draw(s.hp / m.maxHp);
        }
    }
}

// primul jucător cu harta încărcată trimite punctele valide pe care le folosește serverul
function trySendSpawnPoints() {
    if (!wantSpawnPoints || !mapLoaded || !characterLoaded || !socket || !socket.connected) return;
    wantSpawnPoints = false;
    const points = [];
    for (let i = 0; i < 24; i++) {
        const p = pickSpawnPoint();
        if (p) points.push({ x: Math.round(p.x * 100) / 100, z: Math.round(p.z * 100) / 100 });
    }
    let boss = null;
    for (let i = 0; i < 60 && !boss; i++) {
        const p = pickSpawnPoint();
        if (p && Math.hypot(p.x, p.z) > MAP_TARGET_SIZE * 0.22) boss = { x: Math.round(p.x * 100) / 100, z: Math.round(p.z * 100) / 100 };
    }
    if (!boss && points.length) boss = points[0];
    if (points.length >= 5) { socket.emit("spawnPoints", { points: points, boss: boss }); setLoad("world", 0.6); }
    else addChat("Nu am găsit suficiente puncte valide pe hartă pentru monștri.", "#e74c3c");
}

