function sndStartMusic() {
    const pad = sndCtx.createGain();
    pad.gain.value = 0.05;
    pad.connect(sndMusicGain);
    const filt = sndCtx.createBiquadFilter();
    filt.type = "lowpass";
    filt.frequency.value = 320;
    filt.Q.value = 2;
    filt.connect(pad);
    [55, 82.41, 110, 110.7].forEach(function(f, i) {
        const o = sndCtx.createOscillator();
        o.type = i < 2 ? "sawtooth" : "triangle";
        o.frequency.value = f;
        o.detune.value = (i - 1.5) * 5;
        o.connect(filt);
        o.start();
    });
    const lfo = sndCtx.createOscillator();
    lfo.frequency.value = 0.07;
    const lg = sndCtx.createGain();
    lg.gain.value = 140;
    lfo.connect(lg);
    lg.connect(filt.frequency);
    lfo.start();

    sndMusicBus = sndCtx.createGain();
    sndMusicBus.gain.value = 1;
    sndMusicBus.connect(sndMusicGain);
    const delay = sndCtx.createDelay(2);
    delay.delayTime.value = 0.52;
    const fb = sndCtx.createGain();
    fb.gain.value = 0.42;
    const lp = sndCtx.createBiquadFilter();
    lp.type = "lowpass";
    lp.frequency.value = 1800;
    sndMusicBus.connect(delay);
    delay.connect(lp);
    lp.connect(fb);
    fb.connect(delay);
    lp.connect(sndMusicGain);

    musicNextMelody = sndCtx.currentTime + 2;
    musicNextBeat = sndCtx.currentTime + 1;
    musicTimer = setInterval(sndMusicTick, 120);
}

function sndMelodyNote(t) {
    const f = MUSIC_NOTES[Math.floor(Math.random() * MUSIC_NOTES.length)] * (Math.random() < 0.25 ? 2 : 1);
    const o = sndCtx.createOscillator();
    o.type = "triangle";
    o.frequency.setValueAtTime(f, t);
    const g = sndCtx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.11, t + 0.06);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 2.8);
    o.connect(g);
    g.connect(sndMusicBus);
    o.start(t);
    o.stop(t + 3);
}

function sndBossBeat(t, i) {
    // tobă
    const k = sndCtx.createOscillator();
    k.type = "sine";
    k.frequency.setValueAtTime(120, t);
    k.frequency.exponentialRampToValueAtTime(45, t + 0.18);
    const kg = sndCtx.createGain();
    kg.gain.setValueAtTime(0.5, t);
    kg.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    k.connect(kg);
    kg.connect(sndMusicGain);
    k.start(t);
    k.stop(t + 0.25);
    // bas
    const bass = [55, 55, 65.41, 58.27][i % 4];
    const b = sndCtx.createOscillator();
    b.type = "sawtooth";
    b.frequency.setValueAtTime(bass, t);
    const bf = sndCtx.createBiquadFilter();
    bf.type = "lowpass";
    bf.frequency.value = 260;
    const bg = sndCtx.createGain();
    bg.gain.setValueAtTime(0.0001, t);
    bg.gain.linearRampToValueAtTime(0.16, t + 0.02);
    bg.gain.exponentialRampToValueAtTime(0.0001, t + 0.42);
    b.connect(bf);
    bf.connect(bg);
    bg.connect(sndMusicGain);
    b.start(t);
    b.stop(t + 0.45);
    // sunet metalic pe contratimp
    if (sndNoiseBuf) {
        const n = sndCtx.createBufferSource();
        n.buffer = sndNoiseBuf;
        const nf = sndCtx.createBiquadFilter();
        nf.type = "highpass";
        nf.frequency.value = 6000;
        const ng = sndCtx.createGain();
        ng.gain.setValueAtTime(0.0001, t + 0.25);
        ng.gain.linearRampToValueAtTime(0.05, t + 0.26);
        ng.gain.exponentialRampToValueAtTime(0.0001, t + 0.32);
        n.connect(nf);
        nf.connect(ng);
        ng.connect(sndMusicGain);
        n.start(t + 0.25, Math.random());
        n.stop(t + 0.35);
    }
}

function sndMusicTick() {
    if (!sndCtx || !musicOn) return;
    try {
        const now = sndCtx.currentTime;
        const ahead = now + 0.3;
        if (musicNextMelody < ahead) {
            const t = Math.max(musicNextMelody, now);
            sndMelodyNote(t);
            musicNextMelody = t + (musicMode === "boss" ? 0.9 + Math.random() * 0.8 : 2.2 + Math.random() * 3.2);
        }
        if (musicMode === "boss") {
            while (musicNextBeat < ahead) {
                sndBossBeat(Math.max(musicNextBeat, now), musicBeatIdx++);
                musicNextBeat += 0.5;
            }
        } else {
            musicNextBeat = Math.max(musicNextBeat, now);
        }
    } catch (e) {}
}

function toggleMusic() {
    musicOn = !musicOn;
    if (sndMusicGain) sndMusicGain.gain.setTargetAtTime(musicOn ? 0.5 : 0, sndCtx.currentTime, 0.15);
    if (musicOn && sndCtx) { musicNextMelody = sndCtx.currentTime + 1; musicNextBeat = sndCtx.currentTime + 0.5; }
    updateAudioButtons();
    sndSavePrefs();
}

function toggleSfx() {
    sfxOn = !sfxOn;
    if (sndSfxGain) sndSfxGain.gain.setTargetAtTime(sfxOn ? 0.8 : 0, sndCtx.currentTime, 0.05);
    updateAudioButtons();
    sndSavePrefs();
    if (sfxOn) sndClick();
}

/* ====================== ECRAN DE ÎNCĂRCARE ====================== */
const loadState = { map: 0, char: 0, server: 0, world: 0, scan: 0 };
const LOAD_WEIGHTS = { map: 0.5, char: 0.15, server: 0.1, world: 0.2, scan: 0.05 };
const LOAD_LABELS = {
    map: "Se încarcă harta lumii", char: "Se încarcă eroul", server: "Se conectează la server",
    world: "Se creează monștrii și boss-ul", scan: "Se desenează harta mică"
};
const LOAD_ORDER = ["map", "char", "server", "world", "scan"];
const LOAD_TIPS = [
    "Ține apăsat click dreapta și mișcă mouse-ul ca să rotești camera.",
    "Apasă K ca să cheltui punctele de abilitate: Nv.17 → M1 → G1 → P.",
    "Lordul Infernului lasă cristale rare și echipament puternic.",
    "Rostogolește-te (C) ca să scapi de lovitura în sol a boss-ului.",
    "Apasă I pentru inventar și P pentru punctele de caracter.",
    "Trei lovituri la rând cu tasta 1 fac un combo cu daune mari.",
    "Cristalele sunt necesare pentru abilitățile G → P și pentru echipamentul Infernului.",
    "Apasă Tab ca să ții ținta cel mai apropiat dușman."
];
let loadingActive = false, loadShown = 0, loadStartT = 0, loadTimer = null, loadTipIdx = 0, loadTipT = 0;

function setLoad(key, v) {
    if (!(key in loadState)) return;
    v = Math.max(0, Math.min(1, Number(v) || 0));
    if (v > loadState[key]) loadState[key] = v;
}

// fracția descărcată; dacă serverul nu trimite mărimea totală, estimăm
function loadFraction(loaded, total, estimate) {
    if (total > 0) return Math.min(1, loaded / total);
    return loaded / (loaded + (estimate || 8e6));
}

function loadingTarget() {
    let t = 0;
    for (const k in LOAD_WEIGHTS) t += LOAD_WEIGHTS[k] * loadState[k];
    return t;
}

function startLoading() {
    loadingActive = true;
    loadShown = 0;
    loadStartT = performance.now();
    loadTipT = loadStartT;
    for (const k in loadState) loadState[k] = 0;
    const el = document.getElementById("loading-screen");
    el.classList.remove("done");
    el.style.display = "flex";
    loadTipIdx = Math.floor(Math.random() * LOAD_TIPS.length);
    document.getElementById("ld-tip").textContent = LOAD_TIPS[loadTipIdx];
    if (loadTimer) clearInterval(loadTimer);
    loadTimer = setInterval(updateLoadingUI, 50);
    updateLoadingUI();
}

function updateLoadingUI() {
    if (!loadingActive) return;
    const now = performance.now();
    // dacă harta lipsește, scanarea ei nu poate porni: nu așteptăm degeaba
    if (loadState.map >= 1 && loadState.char >= 1 && !mmScan && now - loadStartT > 2500) setLoad("scan", 1);

    const target = loadingTarget();
    loadShown += (target - loadShown) * 0.12 + 0.002;
    if (loadShown > target) loadShown = target;
    const p = Math.min(100, Math.round(loadShown * 100));
    document.getElementById("ld-fill").style.width = p + "%";
    document.getElementById("ld-pct").textContent = p + "%";

    let label = "Aproape gata...";
    for (const k of LOAD_ORDER) {
        if (loadState[k] < 1) { label = LOAD_LABELS[k] + "..."; break; }
    }
    document.getElementById("ld-step").textContent = label;

    if (now - loadTipT > 3500) {
        loadTipT = now;
        loadTipIdx = (loadTipIdx + 1) % LOAD_TIPS.length;
        document.getElementById("ld-tip").textContent = LOAD_TIPS[loadTipIdx];
    }

    const elapsed = now - loadStartT;
    const slow = elapsed > 45000;
    if ((target >= 0.999 && loadShown >= 0.995 && elapsed > 1200) || slow) finishLoading(slow);
}

function finishLoading(slow) {
    if (!loadingActive) return;
    loadingActive = false;
    if (loadTimer) { clearInterval(loadTimer); loadTimer = null; }
    if (!slow) {
        document.getElementById("ld-fill").style.width = "100%";
        document.getElementById("ld-pct").textContent = "100%";
    }
    const el = document.getElementById("loading-screen");
    el.classList.add("done");
    setTimeout(function() { if (!loadingActive) el.style.display = "none"; }, 700);
    addChat(slow ? "⚠️ Serverul răspunde greu; jocul continuă." : "Lumea s-a încărcat. Bun venit, " + heroName + "!", slow ? "#e67e22" : "#2ecc71");
}

/* ====================== EFECTE VIZUALE PENTRU ABILITĂȚI ====================== */
// Fiecare abilitate are propria formă și propria culoare:
// 1 semilună aurie · 2 vortex de lame albastre · 3 cupolă hexagonală aurie · 4 orb violet cu inele
// 5 flăcări roșii · 6 crăpături de lavă, bolovani, praf · 7 trăsnete albastre groase
let SKILL_COLORS = {};
const fx = [];
let glowTex = null, dustTex = null;
const runeTex = {};
let shieldFx = null, shieldFlash = 0;
let warAuraSprite = null, warAuraTimer = 0, rollDustTimer = 0;

function addFx(max, update, dispose) {
    fx.push({ life: 0, max: max, update: update, dispose: dispose || null });
}

function updateFx(delta) {
    for (let i = fx.length - 1; i >= 0; i--) {
        const f = fx[i];
        f.life += delta;
        const t = Math.min(1, f.life / f.max);
        try { f.update(t, delta); } catch (e) { f.life = f.max; }
        if (f.life >= f.max) {
            if (f.dispose) { try { f.dispose(); } catch (e) {} }
            fx.splice(i, 1);
        }
    }
}

function getGlowTex() {
    if (glowTex) return glowTex;
    const c = document.createElement("canvas");
    c.width = 128; c.height = 128;
    const g = c.getContext("2d");
    const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, "rgba(255,255,255,1)");
    grad.addColorStop(0.25, "rgba(255,255,255,0.55)");
    grad.addColorStop(1, "rgba(255,255,255,0)");
    g.fillStyle = grad;
    g.fillRect(0, 0, 128, 128);
    glowTex = new THREE.CanvasTexture(c);
    return glowTex;
}

function getDustTex() {
    if (dustTex) return dustTex;
    const c = document.createElement("canvas");
    c.width = 64; c.height = 64;
    const g = c.getContext("2d");
    const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    grad.addColorStop(0, "rgba(255,255,255,0.9)");
    grad.addColorStop(0.5, "rgba(255,255,255,0.35)");
    grad.addColorStop(1, "rgba(255,255,255,0)");
    g.fillStyle = grad;
    g.fillRect(0, 0, 64, 64);
    dustTex = new THREE.CanvasTexture(c);
    return dustTex;
}

function makeGlowSprite(color, size, opacity) {
    const mat = new THREE.SpriteMaterial({ map: getGlowTex(), color: color, transparent: true, opacity: opacity, blending: THREE.AdditiveBlending, depthWrite: false });
    const sp = new THREE.Sprite(mat);
    sp.scale.setScalar(size);
    return sp;
}

// cerc magic desenat pe canvas (steaua are 5, 6, 7 sau 8 colțuri după variantă)
function getRuneTex(color, variant) {
    const key = color + ":" + variant;
    if (runeTex[key]) return runeTex[key];
    const c = document.createElement("canvas");
    c.width = 256; c.height = 256;
    const g = c.getContext("2d");
    g.translate(128, 128);
    g.strokeStyle = color;
    g.fillStyle = color;
    g.lineCap = "round";
    g.shadowColor = color;
    g.shadowBlur = 10;
    g.lineWidth = 5;
    g.beginPath(); g.arc(0, 0, 120, 0, Math.PI * 2); g.stroke();
    g.lineWidth = 2.5;
    g.beginPath(); g.arc(0, 0, 104, 0, Math.PI * 2); g.stroke();
    g.beginPath(); g.arc(0, 0, 70, 0, Math.PI * 2); g.stroke();
    const n = [5, 6, 7, 8][variant % 4];
    const skip = n === 8 ? 3 : 2;
    g.lineWidth = 3;
    g.beginPath();
    for (let i = 0; i < n; i++) {
        const a1 = -Math.PI / 2 + i / n * Math.PI * 2;
        const a2 = -Math.PI / 2 + ((i + skip) % n) / n * Math.PI * 2;
        g.moveTo(Math.cos(a1) * 104, Math.sin(a1) * 104);
        g.lineTo(Math.cos(a2) * 104, Math.sin(a2) * 104);
    }
    g.stroke();
    g.lineWidth = 2;
    for (let i = 0; i < 24; i++) {
        const a = i / 24 * Math.PI * 2;
        const r1 = 106, r2 = i % 2 ? 114 : 119;
        g.beginPath(); g.moveTo(Math.cos(a) * r1, Math.sin(a) * r1); g.lineTo(Math.cos(a) * r2, Math.sin(a) * r2); g.stroke();
    }
    for (let i = 0; i < n; i++) {
        const a = -Math.PI / 2 + i / n * Math.PI * 2;
        g.beginPath(); g.arc(Math.cos(a) * 104, Math.sin(a) * 104, 5, 0, Math.PI * 2); g.fill();
    }
    g.beginPath(); g.arc(0, 0, 8, 0, Math.PI * 2); g.fill();
    runeTex[key] = new THREE.CanvasTexture(c);
    return runeTex[key];
}

function spawnRuneCircle(x, y, z, hexColor, variant, radius, dur, spin) {
    if (!scene) return;
    const mat = new THREE.MeshBasicMaterial({ map: getRuneTex(hexColor, variant), transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const geo = new THREE.PlaneGeometry(radius * 2, radius * 2);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    const grp = new THREE.Group();
    grp.position.set(x, y + 0.08, z);
    grp.add(mesh);
    scene.add(grp);
    addFx(dur, function(t, dt) {
        grp.rotation.y += spin * dt;
        const env = t < 0.15 ? t / 0.15 : (t > 0.7 ? (1 - t) / 0.3 : 1);
        mat.opacity = 0.95 * env;
        grp.scale.setScalar(0.7 + 0.3 * Math.min(1, t * 4));
    }, function() { scene.remove(grp); geo.dispose(); mat.dispose(); });
}

function spawnDust(x, y, z, count, spread, color) {
    if (!scene) return;
    const tex = getDustTex();
    for (let i = 0; i < count; i++) {
        const mat = new THREE.SpriteMaterial({ map: tex, color: color || 0x8a7a62, transparent: true, opacity: 0.5, depthWrite: false });
        const sp = new THREE.Sprite(mat);
        const a = Math.random() * Math.PI * 2, d = Math.random() * spread;
        sp.position.set(x + Math.cos(a) * d, y + 0.2, z + Math.sin(a) * d);
        const s0 = 0.6 + Math.random() * 0.5;
        sp.scale.setScalar(s0);
        scene.add(sp);
        const vx = Math.cos(a) * (0.8 + Math.random()), vz = Math.sin(a) * (0.8 + Math.random()), vy = 0.6 + Math.random() * 0.8;
        addFx(0.9 + Math.random() * 0.4, function(t, dt) {
            sp.position.x += vx * dt;
            sp.position.y += vy * dt * (1 - t);
            sp.position.z += vz * dt;
            sp.scale.setScalar(s0 * (1 + 2.2 * t));
            mat.opacity = 0.5 * (1 - t);
        }, function() { scene.remove(sp); mat.dispose(); });
    }
}

function castText(n) {
    spawnFloatingText(SKILL_DEFS[n].name + "!", SKILL_COLORS[n] || "#ffd36b",
        new THREE.Vector3(myPos.x, myPos.y + PLAYER_HEIGHT + 0.8, myPos.z), false);
}

/* ---------- 1. Lovitura Sabiei: semilună aurie care taie aerul ---------- */
const CRESCENT_VS = "varying vec2 vUv; void main() { vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }";
const CRESCENT_FS = [
    "varying vec2 vUv; uniform float uProgress; uniform float uFade; uniform vec3 uColA; uniform vec3 uColB;",
    "void main() {",
    "  float head = 1.0 - clamp((uProgress - vUv.x) * 2.5, 0.0, 1.0);",
    "  float vis = step(vUv.x, uProgress);",
    "  float edge = 1.0 - abs(vUv.y - 0.5) * 2.0;",
    "  float a = vis * (0.2 + 0.8 * head) * pow(max(edge, 0.0), 0.6) * uFade;",
    "  vec3 col = mix(uColA, uColB, head);",
    "  gl_FragColor = vec4(col * (0.6 + 0.9 * head), a);",
    "}"
].join("\n");

function crescentGeo(R, W, a0, a1) {
    const N = 36, pos = [], uv = [], idx = [];
    for (let i = 0; i <= N; i++) {
        const t = i / N, a = a0 + (a1 - a0) * t;
        const w = W * Math.pow(Math.sin(Math.PI * t), 0.75) / 2 + 0.02;
        const c = Math.cos(a), sn = Math.sin(a);
        pos.push((R - w) * c, (R - w) * sn, 0, (R + w) * c, (R + w) * sn, 0);
        uv.push(t, 0, t, 1);
        if (i < N) { const k = i * 2; idx.push(k, k + 1, k + 2, k + 1, k + 3, k + 2); }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute("uv", new THREE.Float32BufferAttribute(uv, 2));
    g.setIndex(idx);
    return g;
}

function crescentMat(colA, colB) {
    return new THREE.ShaderMaterial({
        uniforms: { uProgress: { value: 0 }, uFade: { value: 1 }, uColA: { value: new THREE.Color(colA) }, uColB: { value: new THREE.Color(colB) } },
        vertexShader: CRESCENT_VS, fragmentShader: CRESCENT_FS,
        transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending
    });
}

function spawnSwordSlash(x, y, z, rotY, tilt, colorA, colorB) {
    if (!scene) return;
    const diag = (tilt || 0) > 0;           // a doua lovitură din combo: oblică, portocalie
    const dir = diag ? -1 : 1;
    const slashColor = colorA || (diag ? 0xff5a14 : 0xffbb33);
    const highlightColor = colorB || (diag ? 0xfff0c8 : 0xffffff);
    const geo = crescentGeo(2.7, 1.3, dir * 1.05, -dir * 1.05);
    const mat = crescentMat(slashColor, highlightColor);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    const tiltGroup = new THREE.Group();
    tiltGroup.rotation.x = tilt || 0;
    tiltGroup.add(mesh);
    const group = new THREE.Group();
    group.position.set(x, y + 1.0, z);
    group.rotation.y = rotY - Math.PI / 2;
    group.add(tiltGroup);
    scene.add(group);
    group.updateMatrixWorld(true);

    for (let k = 0; k < 14; k++) {
        const a = dir * 1.05 * (1 - 2 * k / 13);
        const p = new THREE.Vector3(2.8 * Math.cos(a), 0, -2.8 * Math.sin(a)).applyMatrix4(tiltGroup.matrixWorld);
        spawnParticle(p.x, p.y, p.z, (Math.random() - 0.5) * 3, 1 + Math.random() * 2, (Math.random() - 0.5) * 3,
            colorA || (diag ? 0xff8a3a : 0xffd45a), 0.1, 0.4);
    }
    addFx(0.3, function(t) {
        mat.uniforms.uProgress.value = t * 1.5;
        mat.uniforms.uFade.value = t < 0.55 ? 1 : (1 - t) / 0.45;
        group.scale.setScalar(1 + 0.12 * t);
    }, function() { scene.remove(group); geo.dispose(); mat.dispose(); });
}

/* ---------- 2. Vârtej de Lame: trei lame albastre care se rotesc ---------- */
function spawnBladeVortex(x, y, z, follow) {
    if (!scene) return;
    const group = new THREE.Group();
    group.position.set(x, y + 0.9, z);
    const mats = [], geos = [];
    for (let i = 0; i < 3; i++) {
        const geo = crescentGeo(2.9, 1.0, 0, 2.3);
        const mat = crescentMat(0x58b0ff, 0xffffff);
        mat.uniforms.uProgress.value = 2;
        const m = new THREE.Mesh(geo, mat);
        m.rotation.x = -Math.PI / 2;
        const holder = new THREE.Group();
        holder.rotation.y = i * Math.PI * 2 / 3;
        holder.position.y = (i - 1) * 0.4;
        holder.add(m);
        group.add(holder);
        mats.push(mat);
        geos.push(geo);
    }
    scene.add(group);
    spawnDust(x, y + 0.05, z, 12, 2.4, 0xaab8c8);
    addFx(0.65, function(t, dt) {
        if (follow) { const p = follow(); group.position.set(p.x, p.y + 0.9, p.z); }
        group.rotation.y += 16 * dt;
        const env = t < 0.12 ? t / 0.12 : (t > 0.65 ? (1 - t) / 0.35 : 1);
        mats.forEach(function(m) { m.uniforms.uFade.value = env; });
        group.scale.setScalar(0.7 + 0.5 * t);
        for (let k = 0; k < 3; k++) {
            const a = Math.random() * Math.PI * 2, r = 1.6 + Math.random() * 1.8;
            spawnParticle(group.position.x + Math.cos(a) * r, group.position.y - 0.7 + Math.random() * 1.6, group.position.z + Math.sin(a) * r,
                -Math.sin(a) * 5, 0.6, Math.cos(a) * 5, 0xcfe8ff, 0.14, 0.4);
        }
    }, function() { scene.remove(group); geos.forEach(function(g) { g.dispose(); }); mats.forEach(function(m) { m.dispose(); }); });
}

/* ---------- 3. Scut Divin: cupolă hexagonală aurie + cerc de rune ---------- */
const DOME_VS = [
    "varying vec3 vNormal; varying vec3 vView; varying vec3 vPos;",
    "void main() {",
    "  vNormal = normalize(normalMatrix * normal);",
    "  vec4 mv = modelViewMatrix * vec4(position, 1.0);",
    "  vView = normalize(-mv.xyz);",
    "  vPos = position;",
    "  gl_Position = projectionMatrix * mv;",
    "}"
].join("\n");
const DOME_FS = [
    "uniform float uTime; uniform float uOpacity; uniform float uFlash; uniform vec3 uColor;",
    "varying vec3 vNormal; varying vec3 vView; varying vec3 vPos;",
    "float hexd(vec2 uv) {",
    "  vec2 r = vec2(1.0, 1.7320508); vec2 h = r * 0.5;",
    "  vec2 a = mod(uv, r) - h; vec2 b = mod(uv - h, r) - h;",
    "  vec2 gv = dot(a, a) < dot(b, b) ? a : b;",
    "  vec2 q = abs(gv);",
    "  return max(dot(q, normalize(vec2(1.0, 1.7320508))), q.x);",
    "}",
    "void main() {",
    "  float fres = pow(1.0 - abs(dot(normalize(vNormal), normalize(vView))), 2.2);",
    "  vec2 uv = vec2(atan(vPos.z, vPos.x) * 2.4, vPos.y * 2.6 - uTime * 0.25);",
    "  float line = smoothstep(0.40, 0.5, hexd(uv));",
    "  float pulse = 0.5 + 0.5 * sin(uTime * 3.0 + vPos.y * 4.0);",
    "  float a = (0.06 + fres * 0.75 + line * 0.38 * (0.6 + 0.4 * pulse) + uFlash * (0.35 + fres)) * uOpacity;",
    "  vec3 col = mix(uColor, vec3(1.0, 0.95, 0.8), clamp(fres * 0.6 + uFlash, 0.0, 1.0));",
    "  gl_FragColor = vec4(col * (0.9 + uFlash), a);",
    "}"
].join("\n");

function createShieldFx() {
    const mat = new THREE.ShaderMaterial({
        uniforms: { uTime: { value: 0 }, uOpacity: { value: 0 }, uFlash: { value: 0 }, uColor: { value: new THREE.Color(0xffd24a) } },
        vertexShader: DOME_VS, fragmentShader: DOME_FS,
        transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending
    });
    const dome = new THREE.Mesh(new THREE.SphereGeometry(1.75, 32, 20), mat);
    dome.position.y = PLAYER_HEIGHT * 0.55;
    const runeMat = new THREE.MeshBasicMaterial({ map: getRuneTex("#ffd24a", 1), transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const rune = new THREE.Mesh(new THREE.PlaneGeometry(4.2, 4.2), runeMat);
    rune.rotation.x = -Math.PI / 2;
    rune.position.y = 0.06;
    const group = new THREE.Group();
    group.add(dome);
    group.add(rune);
    group.visible = false;
    return { group: group, dome: dome, rune: rune, mat: mat, runeMat: runeMat, level: 0 };
}

function updateShieldFx(delta, now) {
    if (!shieldFx) return;
    shieldFx.level += ((isDefending ? 1 : 0) - shieldFx.level) * Math.min(1, 9 * delta);
    if (shieldFlash > 0) shieldFlash = Math.max(0, shieldFlash - delta * 3);
    const lv = shieldFx.level;
    shieldFx.group.visible = lv > 0.02;
    if (!shieldFx.group.visible) return;
    shieldFx.mat.uniforms.uTime.value = now;
    shieldFx.mat.uniforms.uOpacity.value = lv;
    shieldFx.mat.uniforms.uFlash.value = shieldFlash;
    const sc = 0.8 + 0.2 * lv;
    shieldFx.dome.scale.set(sc, sc * 1.15, sc);
    shieldFx.rune.rotation.z += delta * 0.9;
    shieldFx.runeMat.opacity = 0.8 * lv;
}

/* ---------- 4. Sfera de Energie: orb violet cu inele, urmă de cometă ---------- */
function spawnProjectile(x, y, z, dx, dz, mine, color, skillId, mult, splash, visualType) {
    if (!scene) return;
    const classColor = color;
    color = color || 0xb44cff;
    skillId = skillId || 4;
    if (mult === undefined) mult = spellMult;
    const group = new THREE.Group();
    const coreMat = new THREE.MeshBasicMaterial({ color: 0xffe6ff });
    const shellMat = new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false });
    const core = new THREE.Mesh(PARTICLE_GEO, coreMat);
    core.scale.setScalar(0.24);
    const shell = new THREE.Mesh(PARTICLE_GEO, shellMat);
    shell.scale.setScalar(0.46);
    const glow = makeGlowSprite(classColor || 0xa23cff, 2.6, 0.85);
    const accent = classColor || 0xff7bf0;
    const ringMat = new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
    const ringGeo = new THREE.TorusGeometry(0.62, 0.03, 8, 28);
    const ring1 = new THREE.Mesh(ringGeo, ringMat);
    const ring2 = new THREE.Mesh(ringGeo, ringMat);
    ring2.rotation.y = Math.PI / 2;
    const mats = [coreMat, shellMat, glow.material, ringMat], geos = [ringGeo];
    const visualGroup = new THREE.Group();
    visualGroup.rotation.y = Math.atan2(dx, dz);
    function addVisual(geo, mat, x0, y0, z0) {
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(x0 || 0, y0 || 0, z0 || 0);
        visualGroup.add(mesh); mats.push(mat); geos.push(geo);
        return mesh;
    }
    function makeShape(points) {
        const shape = new THREE.Shape();
        shape.moveTo(points[0][0], points[0][1]);
        for (let i = 1; i < points.length; i++) shape.lineTo(points[i][0], points[i][1]);
        shape.closePath();
        return new THREE.ExtrudeGeometry(shape, { depth: 0.11, bevelEnabled: true, bevelThickness: 0.025, bevelSize: 0.025, bevelSegments: 1, steps: 1 });
    }
    if (visualType === "shuriken") {
        core.visible = shell.visible = glow.visible = ring1.visible = ring2.visible = false;
        const spin = new THREE.Group(); visualGroup.add(spin);
        const bladeGeo = makeShape([[0,0.82],[0.15,0.18],[0.73,0],[0.15,-0.18],[0,-0.82],[-0.15,-0.18],[-0.73,0],[-0.15,0.18]]);
        const bladeMat = new THREE.MeshPhongMaterial({ color: color, emissive: color, emissiveIntensity: 0.45, shininess: 90, side: THREE.DoubleSide });
        const blade = new THREE.Mesh(bladeGeo, bladeMat); blade.position.z = -0.055; spin.add(blade); mats.push(bladeMat); geos.push(bladeGeo);
        const hubGeo = new THREE.CylinderGeometry(0.12, 0.12, 0.14, 8);
        const hubMat = new THREE.MeshPhongMaterial({ color: 0xeafaff, emissive: color, emissiveIntensity: 0.7 });
        const hub = addVisual(hubGeo, hubMat, 0, 0, 0); hub.rotation.x = Math.PI / 2;
        visualGroup.userData.spin = spin;
    } else if (visualType === "axe") {
        core.visible = shell.visible = glow.visible = ring1.visible = ring2.visible = false;
        const handleGeo = new THREE.CylinderGeometry(0.045, 0.065, 1.15, 8);
        const handleMat = new THREE.MeshPhongMaterial({ color: 0x75421e, shininess: 40 });
        addVisual(handleGeo, handleMat, 0, 0, 0);
        const bladeGeo = makeShape([[-0.06,0.45],[0.38,0.55],[0.72,0.30],[0.58,0],[0.72,-0.30],[0.38,-0.55],[-0.06,-0.45]]);
        const bladeMat = new THREE.MeshPhongMaterial({ color: color, emissive: color, emissiveIntensity: 0.35, shininess: 100, side: THREE.DoubleSide });
        const blade = addVisual(bladeGeo, bladeMat, 0.15, 0.12, -0.055);
        blade.rotation.y = Math.PI / 2;
        visualGroup.userData.spin = visualGroup;
    } else if (visualType === "bladewave") {
        core.visible = shell.visible = glow.visible = ring1.visible = ring2.visible = false;
        const waveGeo = new THREE.TorusGeometry(0.9, 0.12, 10, 44, Math.PI * 1.45);
        const waveMat = new THREE.MeshPhongMaterial({ color: color, emissive: color, emissiveIntensity: 0.65, transparent: true, opacity: 0.95, shininess: 100, side: THREE.DoubleSide });
        const wave = addVisual(waveGeo, waveMat, 0, 0, 0);
        wave.rotation.z = -Math.PI * 0.28;
        const edgeGeo = new THREE.TorusGeometry(0.98, 0.035, 6, 44, Math.PI * 1.45);
        const edgeMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false });
        addVisual(edgeGeo, edgeMat, 0, 0, 0);
        visualGroup.userData.spin = visualGroup;
    } else if (visualType === "arcane" || visualType === "fireball") {
        const orbGeo = new THREE.IcosahedronGeometry(visualType === "fireball" ? 0.48 : 0.34, 1);
        const orbMat = new THREE.MeshPhongMaterial({ color: color, emissive: color, emissiveIntensity: visualType === "fireball" ? 1.0 : 0.65, shininess: 100, transparent: true, opacity: 0.96 });
        const orb = addVisual(orbGeo, orbMat, 0, 0, 0);
        visualGroup.userData.spin = orb;
        if (visualType === "arcane") {
            const arrowGeo = new THREE.ConeGeometry(0.17, 0.86, 6);
            const arrowMat = new THREE.MeshPhongMaterial({ color: 0xf4fdff, emissive: color, emissiveIntensity: 0.9, shininess: 100 });
            const arrow = addVisual(arrowGeo, arrowMat, 0, 0, 0.62);
            arrow.rotation.x = Math.PI / 2;
            const shaftGeo = new THREE.CylinderGeometry(0.035, 0.055, 0.82, 7);
            const shaftMat = new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
            const shaft = addVisual(shaftGeo, shaftMat, 0, 0, 0.05);
            shaft.rotation.x = Math.PI / 2;
            [0,1,2].forEach(function(i) {
                const orbitGeo = new THREE.TorusGeometry(0.58 + i * 0.11, 0.025, 6, 32);
                const orbitMat = new THREE.MeshBasicMaterial({ color: i ? 0xffffff : color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
                const orbit = addVisual(orbitGeo, orbitMat, 0, 0, 0);
                orbit.rotation.set(i * 0.8, i * 0.55, i * 0.4);
            });
        } else {
            for (let i = 0; i < 4; i++) {
                const flameGeo = new THREE.ConeGeometry(0.19, 0.75 + (i % 2) * 0.25, 6);
                const flameMat = new THREE.MeshBasicMaterial({ color: i % 2 ? 0xff542d : 0xffda73, transparent: true, opacity: 0.86, blending: THREE.AdditiveBlending, depthWrite: false });
                const flame = addVisual(flameGeo, flameMat, (i - 1.5) * 0.16, 0, -0.58 - (i % 2) * 0.12);
                flame.rotation.x = -Math.PI / 2;
            }
        }
    }
    if (visualType) group.add(visualGroup);
    group.add(core);
    group.add(shell);
    group.add(glow);
    group.add(ring1);
    group.add(ring2);
    group.position.set(x, y, z);
    scene.add(group);
    projectiles.push({
        group: group, halo: glow, rings: [ring1, ring2], shell: shell,
        mats: mats, geos: geos, visualGroup: visualType ? visualGroup : null, visualType: visualType,
        dx: dx, dz: dz, dist: 0, t: 0, trail: 0, mine: mine,
        color: color, accent: accent, classColor: classColor, skillId: skillId, mult: mult, splash: splash || 0
    });
}

function removeProjectile(i) {
    const p = projectiles[i];
    scene.remove(p.group);
    p.mats.forEach(function(m) { m.dispose(); });
    p.geos.forEach(function(g) { g.dispose(); });
    projectiles.splice(i, 1);
}

function explodeAt(x, y, z, color) {
    sndImpact(Math.hypot(x - myPos.x, z - myPos.z));
    if (!scene) return;
    const flash = makeGlowSprite(color || 0xd070ff, 1, 1);
    flash.position.set(x, y, z);
    scene.add(flash);
    addFx(0.32, function(t) { flash.scale.setScalar(1.5 + 5.5 * t); flash.material.opacity = (1 - t) * (1 - t); },
        function() { scene.remove(flash); flash.material.dispose(); });

    const ringGeo = new THREE.RingGeometry(0.9, 1, 48);
    const ringMat = new THREE.MeshBasicMaterial({ color: color || 0xff9cf5, transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.position.set(x, y, z);
    ring.rotation.x = -Math.PI / 2;
    scene.add(ring);
    addFx(0.4, function(t) { ring.scale.setScalar(0.4 + 3.6 * t); ringMat.opacity = 0.9 * (1 - t); },
        function() { scene.remove(ring); ringGeo.dispose(); ringMat.dispose(); });

    for (let k = 0; k < 24; k++) {
        const a = Math.random() * Math.PI * 2, up = (Math.random() - 0.3) * 5, sp = 3 + Math.random() * 5;
        spawnParticle(x, y, z, Math.cos(a) * sp, up, Math.sin(a) * sp,
            color ? (k % 3 ? color : 0xffffff) : (k % 3 ? 0xb44cff : 0xff7bf0), 0.2, 0.55);
    }
    for (let k = 0; k < 6; k++) {
        const a = Math.random() * Math.PI * 2;
        spawnParticle(x, y, z, Math.cos(a) * 7, 2 + Math.random() * 3, Math.sin(a) * 7, 0xffffff, 0.12, 0.35);
    }
}

/* ---------- 5. Strigăt de Luptă: undă de sunet + flăcări roșii ---------- */
function spawnWarCryFx(x, y, z) {
    if (!scene) return;
    spawnRuneCircle(x, y, z, "#ff5a2a", 2, 3.4, 1.1, -1.5);
    const geo = new THREE.RingGeometry(0.93, 1, 64);
    const mat = new THREE.MeshBasicMaterial({ color: 0xffd0a0, transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring = new THREE.Mesh(geo, mat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(x, y + 0.6, z);
    scene.add(ring);
    addFx(0.5, function(t) { ring.scale.setScalar(0.5 + 8.5 * t); mat.opacity = 0.9 * (1 - t); },
        function() { scene.remove(ring); geo.dispose(); mat.dispose(); });
    for (let k = 0; k < 40; k++) {
        const a = Math.random() * Math.PI * 2, r = Math.random() * 1.3;
        spawnParticle(x + Math.cos(a) * r, y + 0.1, z + Math.sin(a) * r, Math.cos(a) * 0.8, 4 + Math.random() * 4, Math.sin(a) * 0.8,
            k % 2 ? 0xff4a1a : 0xffb347, 0.2, 0.9);
    }
    addShake(0.35);
}

// cât timp strigătul e activ, în jurul eroului se ridică scântei roșii
function updateWarAura(delta, now) {
    const active = now < buffUntil && !playerDead && !!localPlayerMesh && !!scene;
    if (active && !warAuraSprite) {
        warAuraSprite = makeGlowSprite(0xff4a1a, 3.4, 0.2);
        scene.add(warAuraSprite);
    }
    if (!warAuraSprite) return;
    warAuraSprite.visible = active;
    if (!active) return;
    warAuraSprite.position.set(myPos.x, myPos.y + 1.0 + jumpOffset, myPos.z);
    warAuraSprite.material.opacity = 0.2 + 0.1 * Math.sin(now * 8);
    warAuraTimer -= delta;
    if (warAuraTimer <= 0) {
        warAuraTimer = 0.05;
        const a = Math.random() * Math.PI * 2, r = 0.4 + Math.random() * 0.7;
        spawnParticle(myPos.x + Math.cos(a) * r, myPos.y + 0.1 + jumpOffset, myPos.z + Math.sin(a) * r,
            (Math.random() - 0.5) * 0.6, 2.2 + Math.random() * 1.5, (Math.random() - 0.5) * 0.6,
            Math.random() < 0.5 ? 0xff5a1f : 0xffb347, 0.13, 0.7);
    }
}

/* ---------- 6. Lovitura Seismică: crăpături de lavă, bolovani, praf ---------- */
function ribbonGeo(points, width, ref, mode) {
    const n = points.length, pos = new Float32Array(n * 6), idx = [];
    for (let i = 0; i < n; i++) {
        const p = points[i];
        const q = points[Math.min(n - 1, i + 1)], o = points[Math.max(0, i - 1)];
        const dir = new THREE.Vector3().subVectors(q, o).normalize();
        const side = mode === "up"
            ? new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0, 1, 0))
            : new THREE.Vector3().crossVectors(dir, new THREE.Vector3().subVectors(ref, p));
        if (side.lengthSq() < 1e-8) side.set(1, 0, 0);
        side.normalize().multiplyScalar(width * 0.5 * (1 - 0.35 * Math.abs(i / Math.max(1, n - 1) * 2 - 1)));
        pos[i * 6] = p.x - side.x; pos[i * 6 + 1] = p.y - side.y; pos[i * 6 + 2] = p.z - side.z;
        pos[i * 6 + 3] = p.x + side.x; pos[i * 6 + 4] = p.y + side.y; pos[i * 6 + 5] = p.z + side.z;
        if (i < n - 1) { const k = i * 2; idx.push(k, k + 1, k + 2, k + 1, k + 3, k + 2); }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    g.setIndex(idx);
    return g;
}

function spawnEarthSlam(cx, cz, r) {
    if (!scene) return;
    const y0 = getGroundHeight(cx, cz, myPos.y) + 0.12;
    const group = new THREE.Group();
    scene.add(group);
    const matO = new THREE.MeshBasicMaterial({ color: 0xff6a12, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const matI = new THREE.MeshBasicMaterial({ color: 0xffe08a, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const cracks = [];
    const nCr = 9;
    for (let i = 0; i < nCr; i++) {
        const a = i / nCr * Math.PI * 2 + (Math.random() - 0.5) * 0.35;
        const len = r * (0.7 + Math.random() * 0.45);
        const pts = [];
        let lat = 0;
        for (let k = 0; k <= 9; k++) {
            const d = len * k / 9;
            lat += (Math.random() - 0.5) * 0.7;
            pts.push(new THREE.Vector3(cx + Math.cos(a) * d - Math.sin(a) * lat * 0.5, y0, cz + Math.sin(a) * d + Math.cos(a) * lat * 0.5));
        }
        const go = ribbonGeo(pts, 0.42, null, "up"), gi = ribbonGeo(pts, 0.16, null, "up");
        group.add(new THREE.Mesh(go, matO));
        group.add(new THREE.Mesh(gi, matI));
        cracks.push({ go: go, gi: gi, n: go.index.count });
    }
    const glowMat = new THREE.MeshBasicMaterial({ map: getGlowTex(), color: 0xff7a1a, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const glowGeo = new THREE.PlaneGeometry(r * 2.4, r * 2.4);
    const glow = new THREE.Mesh(glowGeo, glowMat);
    glow.rotation.x = -Math.PI / 2;
    glow.position.set(cx, y0 + 0.02, cz);
    group.add(glow);

    const rockGeo = new THREE.DodecahedronGeometry(1, 0);
    const rockMat = new THREE.MeshStandardMaterial({ color: 0x6b5030, roughness: 0.9, flatShading: true });
    const rocks = [];
    for (let i = 0; i < 14; i++) {
        const m = new THREE.Mesh(rockGeo, rockMat);
        const s0 = 0.14 + Math.random() * 0.2;
        const a = Math.random() * Math.PI * 2, sp = 2 + Math.random() * 4.5;
        m.position.set(cx + Math.cos(a) * Math.random() * 1.5, y0 + 0.2, cz + Math.sin(a) * Math.random() * 1.5);
        m.scale.setScalar(s0);
        group.add(m);
        rocks.push({ m: m, s: s0, vx: Math.cos(a) * sp, vz: Math.sin(a) * sp, vy: 5 + Math.random() * 5, rx: Math.random() * 8, ry: Math.random() * 8, landed: false });
    }
    addFx(1.5, function(t, dt) {
        const reveal = Math.min(1, t * 5);
        cracks.forEach(function(c) { c.go.setDrawRange(0, Math.floor(c.n * reveal)); c.gi.setDrawRange(0, Math.floor(c.n * reveal)); });
        const fade = t < 0.45 ? 1 : (1 - t) / 0.55;
        matO.opacity = 0.9 * fade;
        matI.opacity = fade;
        glowMat.opacity = 0.8 * (1 - t) * (1 - t);
        rocks.forEach(function(rk) {
            if (!rk.landed) {
                rk.vy -= 22 * dt;
                rk.m.position.x += rk.vx * dt;
                rk.m.position.y += rk.vy * dt;
                rk.m.position.z += rk.vz * dt;
                rk.m.rotation.x += rk.rx * dt;
                rk.m.rotation.y += rk.ry * dt;
                if (rk.m.position.y <= y0 && rk.vy < 0) { rk.m.position.y = y0 + 0.05; rk.landed = true; }
            }
            rk.m.scale.setScalar(rk.s * (t > 0.7 ? Math.max(0.01, (1 - t) / 0.3) : 1));
        });
    }, function() {
        scene.remove(group);
        cracks.forEach(function(c) { c.go.dispose(); c.gi.dispose(); });
        glowGeo.dispose(); glowMat.dispose(); rockGeo.dispose(); rockMat.dispose(); matO.dispose(); matI.dispose();
    });

    // undă de praf + nor de praf
    const ringGeo = new THREE.RingGeometry(0.92, 1, 56);
    const ringMat = new THREE.MeshBasicMaterial({ color: 0xd9b27a, transparent: true, opacity: 0.8, side: THREE.DoubleSide, depthWrite: false });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(cx, y0 + 0.05, cz);
    scene.add(ring);
    addFx(0.45, function(t) { ring.scale.setScalar(0.3 + r * t); ringMat.opacity = 0.8 * (1 - t); },
        function() { scene.remove(ring); ringGeo.dispose(); ringMat.dispose(); });
    spawnDust(cx, y0, cz, 16, r * 0.8, 0x8a7556);
    if (Math.hypot(myPos.x - cx, myPos.z - cz) < 40) addShake(0.5);
}

/* ---------- 7. Fulger în Lanț: trăsnete albastre groase, cu ramificații ---------- */
function jaggedPath(a, b, segs, jitter) {
    const pts = [];
    for (let i = 0; i <= segs; i++) {
        const t = i / segs;
        const p = a.clone().lerp(b, t);
        if (i > 0 && i < segs) {
            const j = jitter * Math.sin(Math.PI * t) + 0.08;
            p.x += (Math.random() - 0.5) * 2 * j;
            p.y += (Math.random() - 0.5) * 2 * j;
            p.z += (Math.random() - 0.5) * 2 * j;
        }
        pts.push(p);
    }
    return pts;
}

function spawnBolt(a, b, color) {
    if (!scene) return;
    const boltColor = color || 0x2f8cff;
    const cam = camera ? camera.position : new THREE.Vector3(0, 10, 10);
    const group = new THREE.Group();
    const geos = [], mats = [], base = [];
    function addRibbon(points, width, color, opacity) {
        const geo = ribbonGeo(points, width, cam, "cam");
        const mat = new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: opacity, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
        group.add(new THREE.Mesh(geo, mat));
        geos.push(geo); mats.push(mat); base.push(opacity);
    }
    const main = jaggedPath(a, b, 10, 0.55);
    addRibbon(main, 0.36, boltColor, 0.55);      // strălucire exterioară
    addRibbon(main, 0.16, color ? 0xffffff : 0x9fe4ff, 0.9);
    addRibbon(main, 0.06, 0xffffff, 1.0);       // miez alb
    for (let k = 0; k < 3; k++) {                // ramificații
        const from = main[2 + Math.floor(Math.random() * 6)];
        const d = new THREE.Vector3(Math.random() - 0.5, (Math.random() - 0.5) * 0.6, Math.random() - 0.5).normalize().multiplyScalar(1.5 + Math.random() * 2);
        addRibbon(jaggedPath(from, from.clone().add(d), 5, 0.3), 0.08, color || 0xbfeaff, 0.8);
    }
    const g1 = makeGlowSprite(0x7fd8ff, 2.6, 0.9);
    g1.position.copy(b);
    const g0 = makeGlowSprite(0xffffff, 1.4, 0.9);
    g0.position.copy(a);
    group.add(g1);
    group.add(g0);
    mats.push(g1.material, g0.material);
    base.push(0.9, 0.9);
    scene.add(group);
    bolts.push({ group: group, geos: geos, mats: mats, base: base, life: 0, max: 0.35 });
}

function updateBolts(delta) {
    for (let i = bolts.length - 1; i >= 0; i--) {
        const b = bolts[i];
        b.life += delta;
        const t = b.life / b.max;
        const flick = 0.7 + 0.3 * Math.random();
        for (let k = 0; k < b.mats.length; k++) b.mats[k].opacity = b.base[k] * Math.max(0, 1 - t) * flick;
        if (b.life >= b.max) {
            scene.remove(b.group);
            b.geos.forEach(function(g) { g.dispose(); });
            b.mats.forEach(function(m) { m.dispose(); });
            bolts.splice(i, 1);
        }
    }
}

// scântei electrice în jurul dușmanului lovit
function spawnElectrify(x, y, z, color) {
    if (!scene) return;
    const N = 7;
    const positions = new Float32Array(N * 6);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.LineBasicMaterial({ color: color || 0xbfefff, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
    const lines = new THREE.LineSegments(geo, mat);
    lines.frustumCulled = false;
    scene.add(lines);
    addFx(0.5, function(t) {
        for (let i = 0; i < N; i++) {
            const sx = x + (Math.random() - 0.5) * 1.2, sy = y + 0.4 + Math.random() * 1.6, sz = z + (Math.random() - 0.5) * 1.2;
            positions.set([sx, sy, sz, sx + (Math.random() - 0.5) * 0.9, sy + (Math.random() - 0.5) * 0.9, sz + (Math.random() - 0.5) * 0.9], i * 6);
        }
        geo.attributes.position.needsUpdate = true;
        mat.opacity = 1 - t;
    }, function() { scene.remove(lines); geo.dispose(); mat.dispose(); });
    for (let k = 0; k < 8; k++) {
        spawnParticle(x, y + 1.2, z, (Math.random() - 0.5) * 6, 1 + Math.random() * 3, (Math.random() - 0.5) * 6, color || 0x9fe4ff, 0.1, 0.4);
    }
}

/* ====================== ABILITĂȚI (tastele 1–7) ====================== */
const SKILL_COUNT = 7;
const SKILL_MAX_LV = 38;                        // 1-17 Normal, 18-27 M1-M10, 28-37 G1-G10, 38 = P
const CRYSTAL_STEPS = [1, 1, 1, 1, 2, 2, 2, 3, 3, 4];
let SKILL_DEFS = {};
let skillLv = [0, 1, 0, 0, 0, 0, 0, 0];
let skillPoints = 3;
let skillOpen = false;
let buffUntil = 0, buffAmount = 0;
const bolts = [];

SKILLS[1].id = 1;
SKILLS[2].id = 2;
SKILLS[4].id = 4;
SKILLS[5] = { id: 5, cd: 30, mp: 120, readyAt: 0 };
SKILLS[6] = { id: 6, cd: 8,  mp: 140, range: 6.5, min: 140, max: 200, readyAt: 0 };
SKILLS[7] = { id: 7, cd: 6,  mp: 160, range: 28,  min: 100, max: 150, readyAt: 0 };
